//js:
// 注意：本文件会被构建脚本直接读取，转义层 = 正常 JS 代码（不要 JSON 双写反斜杠）
// 所有变量用 var，禁止 const/let/箭头/尾逗号/中文标识符
var qy71v = {
  host: 'https://www.71v.net',
  d: [],
  d_: [],
  categories: [
    { name: '首页', tid: 'home' },
    { name: '电影', tid: '1' },
    { name: '电视剧', tid: '2' },
    { name: '综艺', tid: '3' },
    { name: '动漫', tid: '4' },
    { name: '短剧', tid: '63' },
    { name: '体育', tid: '17' },
    { name: '纪录片', tid: '60' },
    { name: '游戏', tid: '21' },
    { name: '音乐', tid: '20' },
    { name: '预告片', tid: '11' },
    { name: '公益', tid: '23' }
  ],
  getDoc: function (html) {
    try { return PDFocument(html); } catch (e) { return null; }
  },
  pickImage: function (el) {
    if (!el) return '';
    try {
      var ds = el.attr('data-src') || el.attr('data-original') || el.attr('src') || '';
      if (ds && ds.indexOf('http') !== 0 && ds.indexOf('/') === 0) ds = this.host + ds;
      return ds;
    } catch (e) { return ''; }
  },
  parseCard: function (href, titleText, imgAttr, descText) {
    var self = this;
    if (href && href.indexOf('http') !== 0 && href.indexOf('/') === 0) href = self.host + href;
    var title = (titleText || '').trim();
    var img = '';
    if (imgAttr) {
      img = imgAttr;
      if (img.indexOf('http') !== 0 && img.indexOf('/') === 0) img = self.host + img;
    }
    var desc = (descText || '').trim();
    var re = new RegExp('/voddetail/(\\d+)');
    var m = href.match(re);
    var vid = m ? m[1] : '';
    if (!title) return null;
    return {
      title: title,
      img: img,
      desc: desc,
      col_type: 'movie_3',
      url: $('hiker://empty').rule(function (o) {
        putMyVar('vod_id', o.vod_id);
        putMyVar('vod_name', o.vod_name);
        $.require('qy71v').detail();
      }, { vod_id: vid, vod_name: title })
    };
  },
  extractCards: function (html) {
    var self = this;
    var result = [];
    var doc = self.getDoc(html);
    if (!doc) return result;
    var selectors = [
      '.module-items .module-item',
      '.vodlist .vod-item',
      '.stui-vodlist__item',
      '.public-list-box .public-list-item',
      '.card'
    ];
    var items = null;
    var i, tmp, j, it, tagNameStr, a, img, titleText, titleNode, descNode, descText, href, imgAttr, card;
    for (i = 0; i < selectors.length; i++) {
      try {
        tmp = doc.querySelectorAll(selectors[i]);
        if (tmp && tmp.length >= 2) { items = tmp; break; }
      } catch (e) {}
    }
    if (!items || !items.length) {
      try { items = doc.querySelectorAll('a[href*="/voddetail/"]'); } catch (e) {}
    }
    if (!items) return result;
    var limit = items.length < 60 ? items.length : 60;
    for (j = 0; j < limit; j++) {
      it = items[j];
      card = null;
      tagNameStr = '';
      try { if (it.tagName) tagNameStr = it.tagName(); } catch (e) {}
      a = null;
      if (tagNameStr && tagNameStr.toUpperCase() === 'A') {
        a = it;
      } else {
        try { a = it.querySelector('a[href*="/voddetail/"]'); } catch (e2) {}
        if (!a) { try { a = it.querySelector('a'); } catch (e3) {} }
      }
      if (!a) continue;
      img = null;
      try { img = it.querySelector('img'); } catch (e4) {}
      if (!img && a && a.querySelector) { try { img = a.querySelector('img'); } catch (e5) {} }
      titleText = '';
      try { titleText = a.text() || ''; } catch (e) {}
      titleNode = null;
      try { titleNode = it.querySelector('h3, h4, .title, .vod_title, .module-item-title'); } catch (e) {}
      if (titleNode) { try { titleText = titleNode.text() || titleText; } catch (e) {} }
      titleText = (titleText || '').trim();
      descNode = null;
      try { descNode = it.querySelector('.remarks, .subtitle, .vod_sub, .module-item-subtitle, .module-item-content'); } catch (e) {}
      descText = '';
      if (descNode) { try { descText = descNode.text() || ''; } catch (e) {} }
      href = '';
      try { href = a.attr ? a.attr('href') : ''; } catch (e) {}
      imgAttr = '';
      if (img) {
        try { imgAttr = img.attr ? (img.attr('data-src') || img.attr('data-original') || img.attr('src') || '') : ''; } catch (e) {}
      }
      card = self.parseCard(href, titleText, imgAttr, descText);
      if (card) result.push(card);
    }
    return result;
  },
  home: function () {
    var self = this;
    var d = this.d;
    var d_ = this.d_;
    var pg = MY_PAGE || 1;
    var i;
    if (pg == 1) {
      d_.push({
        title: '搜索',
        col_type: 'input',
        extra: {
          onChange: $.toString(function (v) {
            putMyVar('keyword', v);
            $.require('qy71v').search();
          })
        }
      });
      for (i = 0; i < self.categories.length; i++) {
        (function (tn, tid) {
          d_.push({
            title: getMyVar('cat71', 'home') == tid ? '(' + tn + ')' : tn,
            url: $('#noLoading#').lazyRule(function (id) {
              putMyVar('cat71', id);
              refreshPage(false);
              return 'hiker://empty';
            }, tid),
            col_type: 'scroll_button'
          });
        })(self.categories[i].name, self.categories[i].tid);
      }
      setPreResult(d_);
    }
    var cat = getMyVar('cat71', 'home');
    if (cat === 'home') { self.homePage(pg); } else { self.category(cat, pg); }
    setResult(d);
  },
  homePage: function (pg) {
    var self = this;
    var d = this.d;
    var html;
    try {
      html = request(self.host + '/?pg=' + pg, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('首页请求失败：' + (e && e.message ? e.message : e));
      return;
    }
    var cards = self.extractCards(html);
    if (!cards.length) { d.push({ title: '首页未匹配到数据结构', col_type: 'text_center_1' }); }
    var i;
    for (i = 0; i < cards.length; i++) d.push(cards[i]);
  },
  category: function (tid, pg) {
    var self = this;
    var d = this.d;
    var url = self.host + '/vodtype/' + tid + '-----------' + pg + '---.html';
    var html;
    try {
      html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      try {
        url = self.host + '/vodshow/' + tid + '-----------' + pg + '---.html';
        html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
      } catch (e2) {
        setError('分类请求失败：' + (e2 && e2.message ? e2.message : e2));
        return;
      }
    }
    var cards = self.extractCards(html);
    if (!cards.length) { d.push({ title: '分类页无数据（可能被CF风控）', col_type: 'text_center_1' }); }
    var i;
    for (i = 0; i < cards.length; i++) d.push(cards[i]);
  },
  search: function () {
    var self = this;
    var d = this.d;
    var kw = getMyVar('keyword', '');
    if (!kw) { setResult(d); return; }
    var pg = MY_PAGE || 1;
    var url = self.host + '/vodsearch/-------------' + pg + '---/?wd=' + encodeURIComponent(kw);
    var html;
    try {
      html = request(url, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('搜索失败：' + (e && e.message ? e.message : e));
      return;
    }
    var cards = self.extractCards(html);
    if (!cards.length) { d.push({ title: '没有找到 ' + kw + ' 相关的影片', col_type: 'text_center_1' }); }
    var i;
    for (i = 0; i < cards.length; i++) d.push(cards[i]);
    setResult(d);
  },
  buildEps: function (epList, curSort) {
    var self = this;
    var out = [];
    var list = epList.slice();
    if (curSort === 'desc') list = list.reverse();
    var i;
    var colType = list.length > 3 ? 'text_4' : 'text_2';
    for (i = 0; i < list.length; i++) {
      var parts = list[i].split('$');
      out.push({
        title: parts[0],
        url: self.playUrl(parts[1], parts[2], parts[3]),
        col_type: colType,
        extra: { cls: MY_URL + '_选集', id: parts[1] + '$' + parts[2] + '$' + parts[3] }
      });
    }
    return out;
  },
  detail: function () {
    var self = this;
    var d = this.d;
    var vid = MY_PARAMS.vod_id || getMyVar('vod_id', '');
    var name = MY_PARAMS.vod_name || getMyVar('vod_name', '');
    setPageTitle(name || '详情');
    if (!vid) { setError('缺少vod_id'); setResult(d); return; }
    var html;
    try {
      html = request(self.host + '/voddetail/' + vid + '/', { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('详情请求失败：' + (e && e.message ? e.message : e));
      return;
    }
    var doc = self.getDoc(html);
    if (!doc) { setError('详情HTML解析失败'); setResult(d); return; }
    var vTitle = '';
    try {
      var titleEl = doc.querySelector('h1') || doc.querySelector('h2') || doc.querySelector('.vod_title, .module-info-title, .title');
      vTitle = titleEl ? titleEl.text().trim() : '';
    } catch (e) {}
    if (!vTitle) vTitle = name || '';
    var vPic = '';
    try {
      var img = doc.querySelector('.vod-img img, .module-info-poster img, .stui-content__thumb img, img[src*="/upload/"]');
      vPic = self.pickImage(img);
    } catch (e) {}
    var infoText = '';
    try {
      var info = doc.querySelector('.vod_content, .vod-data, .module-info-content, .stui-content__detail, .vod-info');
      infoText = info ? (info.text() || '').replace(/\s+/g, ' ').trim() : '';
    } catch (e) {}
    var introText = '';
    try {
      var intro = doc.querySelector('.vod_content_intro, .module-info-intro, .detail-content, .vod_content, .stui-content__detail .detail-sketch');
      introText = intro ? (intro.text() || '').trim() : '';
    } catch (e) {}
    d.push({
      title: vTitle || name || '',
      desc: infoText || '',
      img: vPic,
      url: vPic ? (vPic + '#.jpg#') : '',
      col_type: 'movie_1_vertical_pic_blur'
    });
    if (introText) {
      d.push({
        title: '<b><font color="#098AC1">剧情简介</font></b><br>' + introText,
        col_type: 'rich_text',
        extra: { lineSpacing: 6, textSize: 15, lineVisible: true }
      });
    }
    var tabs = [];
    var lists = [];
    try {
      var playAnchors = doc.querySelectorAll('a[href*="/play/"]');
      var groups = {};
      var order = [];
      var k, a, href, mm, sid, nid, ptxt;
      var playRe = new RegExp('/play/(\\d+)-(\\d+)-(\\d+)');
      if (playAnchors && playAnchors.length) {
        for (k = 0; k < playAnchors.length; k++) {
          a = playAnchors[k];
          href = '';
          try { href = a.attr('href') || ''; } catch (e) {}
          mm = href.match(playRe);
          if (!mm) continue;
          sid = mm[2];
          nid = mm[3];
          ptxt = '';
          try { ptxt = (a.text() || '').trim(); } catch (e) {}
          if (!ptxt) continue;
          if (!groups[sid]) { groups[sid] = []; order.push(sid); }
          groups[sid].push({ t: ptxt, nid: nid, href: href, vid: mm[1], sid: sid });
        }
      }
      var lineNames = {};
      var defaultLineIdx = 1;
      try {
        var lineNodes = doc.querySelectorAll('.ylsp-mobile-source-card, .ylsp-pc-source-card, a[href*="/play/"][href*="-1-1"], .module-player-handle-items [class*="source"], [class*="play-from"]');
        if (lineNodes && lineNodes.length) {
          var ln, txt, pureName;
          var numRe = new RegExp('\\d{2,}', 'g');
          for (ln = 0; ln < lineNodes.length && ln < order.length; ln++) {
            txt = '';
            try { txt = (lineNodes[ln].text() || '').replace(/\s+/g, '').trim(); } catch (e) {}
            pureName = txt.replace(numRe, '').replace(/个视频/g, '') || ('线路' + (ln + 1));
            lineNames[order[ln]] = pureName || ('线路' + (ln + 1));
          }
        }
      } catch (e) {}
      var oi, sidKey, arr, lname, eps, seen, ai;
      for (oi = 0; oi < order.length; oi++) {
        sidKey = order[oi];
        arr = groups[sidKey];
        if (!arr || !arr.length) continue;
        lname = lineNames[sidKey] || ('线路' + (defaultLineIdx++));
        tabs.push(lname + '(' + arr.length + ')');
        eps = [];
        seen = {};
        for (ai = 0; ai < arr.length; ai++) {
          if (seen[arr[ai].nid]) continue;
          seen[arr[ai].nid] = true;
          eps.push(arr[ai].t + '$' + arr[ai].sid + '$' + arr[ai].nid + '$' + arr[ai].vid);
        }
        if (eps.length) lists.push(eps);
      }
    } catch (e) {}
    if (lists.length) {
      d.push({ col_type: 'blank_block' });
      storage0.putMyVar('lists71', lists);
      var sortK = getMyVar(MY_URL + 'sort', 'asc');
      d.push({
        title: sortK === 'asc' ? '正序' : '倒序',
        url: $('#noLoading#').lazyRule(function () {
          var ls = storage0.getMyVar('lists71');
          var cur = getMyVar(MY_URL, '0');
          var curSort = getMyVar(MY_URL + 'sort', 'asc');
          var nextSort = curSort === 'asc' ? 'desc' : 'asc';
          var eps2 = self.buildEps(ls[cur] || [], nextSort);
          deleteItemByCls(MY_URL + '_选集');
          addItemBefore(MY_URL + 'footer', eps2);
          updateItem(MY_URL + '_排序按钮', { title: nextSort === 'asc' ? '正序' : '倒序' });
          putMyVar(MY_URL + 'sort', nextSort);
          return 'hiker://empty';
        }),
        col_type: 'flex_button',
        extra: { id: MY_URL + '_排序按钮' }
      });
      var ti;
      for (ti = 0; ti < tabs.length; ti++) {
        (function (tname, tid) {
          d.push({
            title: getMyVar(MY_URL, '0') == String(tid) ? '(' + tname + ')' : tname,
            url: $('#noLoading#').lazyRule(function (tabsArr, id) {
              var ls2 = storage0.getMyVar('lists71');
              var sort2 = getMyVar(MY_URL + 'sort', 'asc');
              var x;
              for (x = 0; x < tabsArr.length; x++) {
                updateItem(MY_URL + '_线路' + x, { title: id == x ? '(' + tabsArr[x] + ')' : tabsArr[x] });
              }
              putMyVar(MY_URL, String(id));
              var eps3 = self.buildEps(ls2[getMyVar(MY_URL, '0')] || [], sort2);
              deleteItemByCls(MY_URL + '_选集');
              addItemBefore(MY_URL + 'footer', eps3);
              return 'hiker://empty';
            }, tabs, tid),
            col_type: 'flex_button',
            extra: { id: MY_URL + '_线路' + tid }
          });
        })(tabs[ti], ti);
      }
      var curList = lists[getMyVar(MY_URL, '0')] || [];
      var epsInit = self.buildEps(curList, sortK);
      var gi;
      for (gi = 0; gi < epsInit.length; gi++) d.push(epsInit[gi]);
      d.push({ col_type: 'big_blank_block', extra: { id: MY_URL + 'footer' } });
    } else {
      d.push({ title: '未解析到播放剧集（详情页结构可能未匹配）', col_type: 'text_center_1' });
    }
    setResult(d);
  },
  playUrl: function (sid, nid, vid) {
    return $('').lazyRule(function (s, n, v) {
      return $.require('qy71v').play(s, n, v);
    }, sid, nid, vid);
  },
  play: function (sid, nid, vid) {
    var self = this;
    var p = self.host + '/play/' + vid + '-' + sid + '-' + nid + '/';
    var html;
    try {
      html = request(p, { headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 15_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15A148' } });
    } catch (e) {
      setError('播放页请求失败：' + (e && e.message ? e.message : e));
      return 'hiker://empty';
    }
    var real = '';
    try {
      var playerRe = new RegExp('var\\s+player_aaaa\\s*=\\s*(\\{[\\s\\S]*?\\})\\s*;');
      var m = html.match(playerRe);
      if (m) {
        var obj = JSON.parse(m[1]);
        var rawUrl = obj && obj.url;
        if (rawUrl) {
          var enc = String(obj.encrypt || '0');
          if (enc === '1') { try { rawUrl = unescape(rawUrl); } catch (e) {} }
          else if (enc === '2') { try { if (typeof atob === 'function') rawUrl = unescape(atob(rawUrl)); } catch (e) {} }
          real = rawUrl;
        }
      }
    } catch (e) {
      setError('解析player_aaaa失败：' + (e && e.message ? e.message : e));
      return 'hiker://empty';
    }
    if (!real) {
      try {
        var urlRe = new RegExp('https?://[^"\')\\s]+\\.(?:m3u8|mp4|flv)(?:\\?[^"\')\\s]*)?');
        var mm = html.match(urlRe);
        if (mm) real = mm[0];
      } catch (e) {}
    }
    if (!real) {
      setError('播放地址为空（可能被CF风控或接口变了）');
      return 'hiker://empty';
    }
    return real;
  }
};
$.exports = qy71v;
